INDEX_HTML = r'''<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>CoA Raid Intelligence</title>
<style>
:root{color-scheme:dark;--bg:#0b1020;--panel:#131b2f;--line:#2a3754;--text:#edf2ff;--muted:#9ba9c5;--accent:#7c9cff;--ok:#72d6a0;--danger:#ff7f91}*{box-sizing:border-box}body{margin:0;font-family:Segoe UI,Arial,sans-serif;background:linear-gradient(140deg,#08101f,#111a31);color:var(--text)}header{padding:22px 28px;border-bottom:1px solid var(--line);background:#0a1122}h1{margin:0 0 5px}.muted{color:var(--muted)}main{max-width:1500px;margin:auto;padding:22px;display:grid;grid-template-columns:minmax(700px,1fr) 320px;gap:18px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:14px}.toolbar{padding:15px;display:flex;gap:12px;align-items:end;border-bottom:1px solid var(--line)}label{display:grid;gap:5px;color:var(--muted);font-size:13px}select,input,button{border:1px solid var(--line);border-radius:8px;background:#0d1528;color:var(--text);padding:8px 9px}button{background:var(--accent);color:#081020;font-weight:700;cursor:pointer}table{width:100%;border-collapse:collapse}th,td{padding:8px;border-bottom:1px solid var(--line);text-align:left}th{color:var(--muted);font-size:12px}td input,td select{width:100%}tr.inactive{display:none}.summary{padding:16px;display:grid;gap:12px;height:max-content}.metric{padding:13px;background:#0d1528;border:1px solid var(--line);border-radius:10px}.metric strong{display:block;font-size:28px;color:var(--ok)}.errors{color:var(--danger);font-size:13px}@media(max-width:1000px){main{grid-template-columns:1fr}}
</style></head><body>
<header><h1>CoA Raid Intelligence</h1><div class="muted">Локальный конструктор рейда • без Excel • данные остаются на этом компьютере</div></header>
<main><section class="panel"><div class="toolbar"><label>Формат<select id="format"><option>FLEX</option><option>10</option><option selected>25</option><option>40</option></select></label><label>Целевой размер<input id="target" type="number" min="1" max="40" value="25"></label><button id="recalc">Пересчитать</button></div><div style="overflow:auto;max-height:calc(100vh - 180px)"><table><thead><tr><th>#</th><th>Игрок</th><th>Класс</th><th>Спек</th><th>Роль</th><th>Lock</th></tr></thead><tbody id="slots"></tbody></table></div></section>
<aside class="panel summary"><div class="metric"><strong id="filled">0</strong><span class="muted">заполнено</span></div><div class="metric"><strong id="remaining">25</strong><span class="muted">осталось</span></div><div><b>Роли</b><div class="muted" id="roles">Нет заполненных ролей</div></div><div><b>Проверки</b><div class="errors" id="errors">Ошибок нет</div></div></aside></main>
<script>
const tbody=document.getElementById('slots');for(let i=1;i<=40;i++)tbody.insertAdjacentHTML('beforeend',`<tr data-slot="${i}"><td>${i}</td><td><input class="player"></td><td><input class="class"></td><td><input class="spec"></td><td><select class="role"><option value=""></option><option>Танк</option><option>Хил</option><option>ДД</option><option>Саппорт</option></select></td><td><input class="locked" type="checkbox"></td></tr>`);
const format=document.getElementById('format'),target=document.getElementById('target');
function requestBody(){return{raid_format:format.value,target_size:Number(target.value),slots:[...tbody.rows].map(r=>({slot_no:Number(r.dataset.slot),player_name:r.querySelector('.player').value,class_code:r.querySelector('.class').value,spec_code:r.querySelector('.spec').value,role:r.querySelector('.role').value,locked:r.querySelector('.locked').checked})).filter(x=>x.player_name||x.class_code||x.spec_code||x.role||x.locked)}}
async function recalc(){const res=await fetch('/api/plans/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(requestBody())});const data=await res.json();if(!res.ok){errors.textContent=data.detail?.[0]?.msg||'Ошибка расчёта';return}data.slots.forEach(s=>tbody.querySelector(`[data-slot="${s.slot_no}"]`).classList.toggle('inactive',!s.active));filled.textContent=data.filled_slots;remaining.textContent=data.remaining_slots;roles.innerHTML=Object.entries(data.role_counts).map(([k,v])=>`${k}: <b>${v}</b>`).join('<br>')||'Нет заполненных ролей';errors.innerHTML=data.validation_errors.join('<br>')||'Ошибок нет'}
function syncFormat(){const fixed={'10':10,'25':25,'40':40};if(fixed[format.value]){target.value=fixed[format.value];target.disabled=true}else target.disabled=false;recalc()}format.addEventListener('change',syncFormat);target.addEventListener('change',recalc);document.getElementById('recalc').addEventListener('click',recalc);tbody.addEventListener('change',recalc);syncFormat();
</script></body></html>'''
